"""Gemini adapter for Playwright script generation.

Mirrors the pattern in testlyn_api/services/gemini.py — creds-missing fallback
returns a hand-authored template so the system stays deterministic without GCP.
"""

from __future__ import annotations

import structlog

from testlyn_api.config import get_settings

log = structlog.get_logger(__name__)

_DEFAULT_LOCATOR_STRATEGIES = [
    "data-testid attribute",
    "ARIA role + accessible name",
    "CSS class (last-resort fallback)",
]

_SCRIPT_TEMPLATE = """\
import {{ test, expect }} from '@playwright/test';

// Auto-generated by Testlyn AI — review before committing to CI.
// Target: {target_url}

test.describe('Generated functional suite', () => {{
  test('page loads and is interactive', async ({{ page }}) => {{
    await page.goto('{target_url}');
    await expect(page).toHaveTitle(/.+/);
    // TODO: add assertions from prompt / PRD
  }});
}});
"""

_CANNED_NOTE = (
    "// NOTE: Vertex AI credentials unavailable — returning baseline template.\n"
    "// Set up Workload Identity to enable AI-generated tests.\n\n"
)


async def generate_playwright_script(
    *,
    prompt: str | None,
    prd_file: str | None,
    target_url: str | None,
) -> tuple[str, list[str]]:
    """Return (script_ts, locator_strategies).

    Calls Gemini 3.1 Flash-Lite via Vertex AI. On creds-missing returns a
    template + default strategies so tests remain deterministic.
    """
    settings = get_settings()
    model_id = settings.gemini_model
    project = settings.gcp_project_id
    location = settings.vertex_ai_location

    context_parts: list[str] = []
    if prompt:
        context_parts.append(f"User prompt:\n{prompt}")
    if prd_file:
        context_parts.append(f"PRD file URI (GCS): {prd_file}")
    if target_url:
        context_parts.append(f"Target URL: {target_url}")

    full_prompt = (
        "You are an expert Playwright TypeScript test author writing for a developer audience.\n"
        "Generate a complete Playwright test file (.ts) that:\n"
        "- Uses @playwright/test\n"
        "- Prefers data-testid selectors, then ARIA roles, then CSS as last resort\n"
        "- Adds a comment per step explaining intent\n"
        "- Covers the user journey described below\n\n"
        + "\n".join(context_parts)
        + "\n\nReturn ONLY the TypeScript file contents, no markdown fences."
    )

    fallback_script = _CANNED_NOTE + _SCRIPT_TEMPLATE.format(
        target_url=target_url or "https://example.com"
    )

    try:
        import google.auth
        import google.auth.exceptions
        from google.cloud import aiplatform

        try:
            credentials, _ = google.auth.default(
                scopes=["https://www.googleapis.com/auth/cloud-platform"]
            )
        except google.auth.exceptions.DefaultCredentialsError:
            log.warning("functional_gemini.creds_missing", model=model_id)
            return fallback_script, _DEFAULT_LOCATOR_STRATEGIES

        aiplatform.init(project=project, location=location, credentials=credentials)

        from vertexai.generative_models import GenerativeModel

        model = GenerativeModel(model_id)
        response = await model.generate_content_async(full_prompt)
        script_ts: str = response.text

        return script_ts, _DEFAULT_LOCATOR_STRATEGIES

    except ImportError:
        log.warning(
            "functional_gemini.creds_missing",
            model=model_id,
            detail="google-cloud-aiplatform not installed",
        )
        return fallback_script, _DEFAULT_LOCATOR_STRATEGIES
    except Exception as exc:
        log.warning(
            "functional_gemini.creds_missing",
            model=model_id,
            detail=str(exc),
        )
        return fallback_script, _DEFAULT_LOCATOR_STRATEGIES
